def _path_size_bytes(target: Path) -> int:
    try:
        if target.is_file():
            return int(target.stat().st_size)
        if not target.exists():
            return 0
        total = 0
        for fp in target.rglob("*"):
            try:
                if fp.is_file():
                    total += int(fp.stat().st_size)
            except Exception:
                continue
        return total
    except Exception:
        return 0

